import{_ as i,a as t,a3 as a,o as n}from"./chunks/framework.7XZN1PIK.js";const h=JSON.parse('{"title":"Using /rubber-duck in Copilot: Get a Second Opinion from an Independent Agent","description":"","frontmatter":{},"headers":[],"relativePath":"devdoc/userdoc/copilot/rubberDuck.md","filePath":"devdoc/userdoc/copilot/rubberDuck.md","lastUpdated":1790266992000}'),o={name:"devdoc/userdoc/copilot/rubberDuck.md"};function s(r,e,l,c,d,u){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="using-rubber-duck-in-copilot-get-a-second-opinion-from-an-independent-agent" tabindex="-1">Using <code>/rubber-duck</code> in Copilot: Get a Second Opinion from an Independent Agent <a class="header-anchor" href="#using-rubber-duck-in-copilot-get-a-second-opinion-from-an-independent-agent" aria-label="Permalink to &quot;Using `/rubber-duck` in Copilot: Get a Second Opinion from an Independent Agent&quot;">​</a></h1><p>Most developers have heard of the classic &quot;rubber duck debugging&quot; technique: Explain the problem out loud to a rubber duck and, somehow, the solution often reveals itself.</p><p>It&#39;s true. The act of vocalizing a problem to someone (or something) forces you to slow down, clarify your thinking, and identify gaps in your understanding.</p><p>I&#39;ve tried a modern variation by talking through problems with my cat. The results have been mixed. While she&#39;s an excellent listener, her troubleshooting advice typically involves walking across the keyboard, closing terminals, or demanding food halfway through the explanation.</p><p>Fortunately, GitHub Copilot&#39;s <code>/rubber-duck</code> offers a much more productive way to challenge your thinking.</p><h2 id="what-is-rubber-duck" tabindex="-1">What Is <code>/rubber-duck</code>? <a class="header-anchor" href="#what-is-rubber-duck" aria-label="Permalink to &quot;What Is `/rubber-duck`?&quot;">​</a></h2><p><code>/rubber-duck</code> is a slash command that invokes the Rubber Duck agent to provide an independent second opinion.</p><p><code>/rubber-duck</code> acts like an independent reviewer, examining your ideas, plans, and implementations from a fresh perspective. It is designed to challenge your assumptions and surface risks, edge cases, and alternative approaches.</p><p>This can help you:</p><ul><li>Uncover hidden assumptions</li><li>Identify blind spots</li><li>Challenge architectural decisions</li><li>Surface edge cases</li><li>Highlight risks before they become problems</li></ul><p>Think of it as having another experienced engineer review your approach before you invest time implementing it.</p><p>One caveat: <code>/rubber-duck</code> is intended to complement, not replace, your normal development and review processes. Its suggestions should be validated with tests and, where appropriate, a formal security review, human peer review, and authoritative project or product documentation. Treat its feedback as a source of questions and possible risks rather than as a definitive assessment.</p><h2 id="when-should-you-use-it" tabindex="-1">When Should You Use It? <a class="header-anchor" href="#when-should-you-use-it" aria-label="Permalink to &quot;When Should You Use It?&quot;">​</a></h2><p>The best time to engage <code>/rubber-duck</code> is whenever the cost of being wrong is high or the solution space is complex.</p><h2 id="how-to-use-it" tabindex="-1">How to Use It <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to Use It&quot;">​</a></h2><p>Enter <code>/rubber-duck</code> in GitHub Copilot Chat, followed by a specific question or request for review. The command is available wherever the Rubber Duck agent is configured, including supported VS Code Copilot Chat environments. It can inspect the current conversation, relevant files in your workspace, open or selected code, and other available project context. For the most useful response, describe the decision, implementation, or change you want reviewed and identify the risks or questions you want it to consider.</p><h3 id="scenario-1-reviewing-a-new-feature-design" tabindex="-1">Scenario 1: Reviewing a New Feature Design <a class="header-anchor" href="#scenario-1-reviewing-a-new-feature-design" aria-label="Permalink to &quot;Scenario 1: Reviewing a New Feature Design&quot;">​</a></h3><p>Before writing a single line of code, ask <code>/rubber-duck</code> to critique your implementation plan.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rubber-duck Review our plan for implementing dark mode across the web application. Identify any accessibility concerns, browser compatibility issues, or edge cases we may have overlooked.</span></span></code></pre></div><p>The review might remind you to consider:</p><ul><li>High-contrast accessibility modes</li><li>User preference persistence</li><li>Embedded third-party components</li><li>Theme switching performance</li></ul><p>Finding these issues before you begin coding could save significant rework later.</p><h3 id="scenario-2-validating-a-migration-plan" tabindex="-1">Scenario 2: Validating a Migration Plan <a class="header-anchor" href="#scenario-2-validating-a-migration-plan" aria-label="Permalink to &quot;Scenario 2: Validating a Migration Plan&quot;">​</a></h3><p>Migrations are one of the highest-risk activities in software development.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rubber-duck Review our migration from SQL Server to PostgreSQL. Identify rollback concerns, data integrity risks, deployment issues, or operational blind spots.</span></span></code></pre></div><p>A second review can reveal:</p><ul><li>Missing rollback procedures</li><li>Data conversion challenges</li><li>Monitoring requirements</li><li>Downtime assumptions</li></ul><h3 id="scenario-3-challenging-security-decisions" tabindex="-1">Scenario 3: Challenging Security Decisions <a class="header-anchor" href="#scenario-3-challenging-security-decisions" aria-label="Permalink to &quot;Scenario 3: Challenging Security Decisions&quot;">​</a></h3><p>Security issues often hide in assumptions.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rubber-duck Review our approach for introducing API key authentication between services. Highlight possible attack vectors, secret-management concerns, and operational risks.</span></span></code></pre></div><p>This often uncovers concerns involving:</p><ul><li>Secret rotation</li><li>Credential storage</li><li>Logging sensitive information</li><li>Key revocation procedures</li></ul><h3 id="scenario-4-before-submitting-a-pull-request" tabindex="-1">Scenario 4: Before Submitting a Pull Request <a class="header-anchor" href="#scenario-4-before-submitting-a-pull-request" aria-label="Permalink to &quot;Scenario 4: Before Submitting a Pull Request&quot;">​</a></h3><p>A final sanity check before requesting human review can be extremely valuable.</p><p>Example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/rubber-duck Analyze the changes in my current branch. What concerns would a senior reviewer likely raise during a pull request review?</span></span></code></pre></div><p>This often identifies:</p><ul><li>Missing tests</li><li>Naming inconsistencies</li><li>Error handling gaps</li><li>Documentation omissions</li></ul><h3 id="why-it-works" tabindex="-1">Why It Works <a class="header-anchor" href="#why-it-works" aria-label="Permalink to &quot;Why It Works&quot;">​</a></h3><p>One of the biggest challenges when solving technical problems is becoming too close to the solution. Once you&#39;ve spent hours designing, coding, or debugging, it&#39;s easy to miss flaws that would be obvious to someone encountering the problem for the first time.</p><p><code>/rubber-duck</code> helps break that tunnel vision by introducing an independent perspective. It won&#39;t replace peer reviews or architecture discussions, but it can help you discover issues earlier, improve design quality, and approach decisions more critically.</p><p>The next time you&#39;re preparing to implement a major feature, refactor a subsystem, roll out a migration, or submit a pull request, ask <code>/rubber-duck</code> to challenge your thinking and identify what you might be missing. I even used <code>/rubber-duck</code> to help me with this article.</p>',45)])])}const b=i(o,[["render",s]]);export{h as __pageData,b as default};
